<script lang="ts">
import {onMount} from 'svelte';import {loadBrowsers,type Preferences,type InstalledBrowser} from './bridge';import Icon from './Icon.svelte';import Choice from './Choice.svelte';
let {preferences,t,onchange,onfolder}:{preferences:Preferences;t:(key:string)=>string;onchange:(key:keyof Preferences,value:boolean|string)=>void;onfolder:()=>void}=$props();
let browsers=$state<InstalledBrowser[]|null>(null);const supportText={supported:'Работает',planned:'Планируется',unsupported:'Не поддерживается'};
onMount(()=>{let current=true;loadBrowsers().then(value=>{if(current)browsers=value;}).catch(()=>{if(current)browsers=[];});return()=>{current=false;};});
const groups=[{title:'Диагностика и звук',rows:[{key:'diagnostics' as const,title:'Запись диагностики',hint:'Сохранять страницы, снимки и ошибки. Таймлайн записывается всегда.',icon:'bug'},{key:'sound' as const,title:'Звуковые уведомления',hint:'Сигнал повторяется, пока требуется участие: выбор офиса, капча или подтверждение брони. Интервал — в «Таймингах» профиля.',icon:'bell'}]},{title:'Обновления',rows:[{key:'automatic_updates' as const,title:'Автоматически проверять обновления',hint:'Служба обновлений ещё не подключена к Rust preview.',icon:'download'}]}];
</script>
<div class="settings-preferences">{#each groups as group}<section><h2>{t(group.title)}</h2><div class="setting-rows">{#each group.rows as row}<div class="setting-row"><Icon name={row.icon} size={20}/><div><strong>{t(row.title)}</strong><small>{t(row.hint)}</small></div><button type="button" class="switch" role="switch" aria-label={t(row.title)} aria-checked={preferences[row.key]} onclick={()=>onchange(row.key,!preferences[row.key])}><span></span></button></div>{/each}</div>{#if group.title==='Диагностика и звук'}<button type="button" class="flat-action" onclick={onfolder}><Icon name="folder" size={18}/>{t('Открыть папку диагностики')}</button>{/if}</section>{/each}<section><h2>{t('Интерфейс')}</h2><div class="interface-preferences"><Choice label={t('Язык')} icon="globe" value={preferences.language} options={[{value:'ru',label:'RU · Русский'},{value:'en',label:'EN · English'},{value:'es',label:'ES · Español'}]} onchange={value=>onchange('language',value)}/><div class="setting-row"><Icon name="sun" size={20}/><div><strong>{t('Тёмная тема')}</strong><small>{t('Изменить оформление приложения')}</small></div><button type="button" class="switch" role="switch" aria-label={t('Тёмная тема')} aria-checked={preferences.dark} onclick={()=>onchange('dark',!preferences.dark)}><span></span></button></div></div></section><section><h2>{t('Браузер для поиска')}</h2><p class="muted">{t('Поиск идёт в отдельном профиле приложения. Сейчас работает только Firefox.')}</p>{#if browsers&&browsers.length}<div class="setting-rows">{#each browsers as browser}<div class="setting-row"><Icon name="globe" size={20}/><div><strong>{browser.name}{browser.version?' '+browser.version:''}</strong></div><span class={browser.support==='supported'?'':'muted'}>{t(supportText[browser.support])}</span></div>{/each}</div>{:else if browsers}<p class="muted">{t('Подходящий браузер не найден')}</p>{/if}</section></div>
